INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die DMZ ein physischer Bereich im Netzwerk?', 2, '[{"text": "Nein", "correct": true, "because": "Logisches Sicherheitskonzept"}, {"text": "Ja", "correct": false, "because": "Nicht physisch abgegrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hauptfunktion hat eine DMZ?', 3, '[{"text": "Sicherheitszone für externe Dienste", "correct": true, "because": "Schutz des internen Netzwerks"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht primäre Aufgabe"}, {"text": "IP-Adressvergabe", "correct": false, "because": "Das macht DHCP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Geräte stehen typischerweise in einer DMZ?', 5, '[{"text": "Webserver", "correct": true, "because": "Extern zugänglich"}, {"text": "Mailserver", "correct": true, "because": "Öffentlich erreichbar"}, {"text": "Interne Workstations", "correct": false, "because": "Gehören ins LAN"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die DMZ schützt das interne Netzwerk. b) Sie ist immer öffentlich zugänglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zugriff wird kontrolliert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Einrichtung einer DMZ?', 4, '[{"text": "Firewall-Regeln", "correct": false, "because": "Sichern den Zugriff"}, {"text": "Netzwerksegmentierung", "correct": false, "because": "Isolierung nötig"}, {"text": "Serverfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die DMZ im internen Netzwerk liegt?', 2, '[{"text": "Nein", "correct": true, "because": "Zwischen intern und extern"}, {"text": "Ja", "correct": false, "because": "Separates Segment"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Firewall bei einer DMZ?', 3, '[{"text": "Kontrolliert Datenverkehr", "correct": true, "because": "Filtert Zugriffe"}, {"text": "Vergibt IP-Adressen", "correct": false, "because": "Das ist DHCP"}, {"text": "Speichert Daten", "correct": false, "because": "Keine Speicherfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine DMZ?', 5, '[{"text": "Erhöhte Sicherheit", "correct": true, "because": "Isoliert externe Dienste"}, {"text": "Kontrolle über Zugriffe", "correct": true, "because": "Firewall-Regeln"}, {"text": "Schnellere Datenübertragung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die DMZ trennt Netzwerke. b) Sie macht Firewalls überflüssig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Firewalls nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine DMZ?', 4, '[{"text": "Firewall", "correct": false, "because": "Schutz essenziell"}, {"text": "Separate IP-Bereiche", "correct": false, "because": "Segmentierung"}, {"text": "Physische Serverräume", "correct": true, "because": "Logisch definiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die DMZ dasselbe wie das LAN?', 2, '[{"text": "Nein", "correct": true, "because": "Getrennte Zonen"}, {"text": "Ja", "correct": false, "because": "LAN ist intern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dienste laufen typischerweise in einer DMZ?', 4, '[{"text": "Webserver", "correct": true, "because": "Extern erreichbar"}, {"text": "DNS-Server", "correct": true, "because": "Öffentlich genutzt"}, {"text": "Interne Datenbanken", "correct": false, "because": "Im LAN geschützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die DMZ keine Sicherheitsvorkehrungen braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Firewall nötig"}, {"text": "Ja", "correct": false, "because": "Sicherheit essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einrichtung einer DMZ?', 3, '[{"text": "Sicherheitsregeln", "correct": true, "because": "Schutz gewährleisten"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Sekundär"}, {"text": "Serverdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die DMZ isoliert externe Dienste. b) Sie liegt im internen Netzwerk.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zwischenbereich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sichern eine DMZ?', 5, '[{"text": "Firewall", "correct": true, "because": "Filtert Verkehr"}, {"text": "IDS/IPS", "correct": true, "because": "Erkennt Angriffe"}, {"text": "Router-LEDs", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer DMZ unwichtig?', 3, '[{"text": "Zugriffskontrolle", "correct": false, "because": "Kernaufgabe"}, {"text": "Segmentierung", "correct": false, "because": "Isolierung nötig"}, {"text": "Serverhöhe", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die DMZ ohne Firewall betrieben werden?', 3, '[{"text": "Nein", "correct": true, "because": "Sicherheit zentral"}, {"text": "Ja", "correct": false, "because": "Firewall erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die DMZ interne Datenbanken schützt?', 2, '[{"text": "Nein", "correct": true, "because": "Datenbanken im LAN"}, {"text": "Ja", "correct": false, "because": "DMZ für externe Dienste"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht die DMZ sicher?', 4, '[{"text": "Netzwerktrennung", "correct": true, "because": "Isoliert Bereiche"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Manuelle Überwachung", "correct": false, "because": "Automatisiert besser"}]');
